    result.push({type:normalized,values:v});x=v.at(-2);y=v.at(-1);if(type==='M'){startX=x;startY=y;command=relative?'l':'L';}lastControl=normalized==='C'?v.slice(2,4):normalized==='Q'?v.slice(0,2):null;lastType=normalized;
